import os,json,re
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
def load():
    G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def transform(g):
    H,W=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    sep=max((c for c in cnt if c!=bg), key=lambda c: sum(r.count(c) for r in g))
    # find separator row/col: full lines of sep
    srow=[i for i in range(H) if all(g[i][j]==sep for j in range(W))]
    scol=[j for j in range(W) if all(g[i][j]==sep for i in range(H))]
    rs=[i for i in range(H) if i not in srow]; cs=[j for j in range(W) if j not in scol]
    # group contiguous
    def groups(idx):
        out=[];cur=[idx[0]]
        for i in idx[1:]:
            if i==cur[-1]+1: cur.append(i)
            else: out.append(cur);cur=[i]
        out.append(cur);return out
    R=groups(rs); C=groups(cs)
    # tile = region containing non-bg, non-sep cells
    tile=None
    for rr in R:
        for cc in C:
            if any(g[i][j] not in (bg,sep) for i in rr for j in cc):
                tile=[[g[i][j] for j in cc] for i in rr]
    out=[row[:] for row in g]
    for i,i0 in enumerate(srow): out[i0]=[sep]*W
    for j in scol:
        for i in range(H): out[i][j]=sep
    for rr in R:
        for cc in C:
            th,tw=len(tile),len(tile[0])
            for i in range(len(rr)):
                for j in range(len(cc)):
                    out[rr[i]][cc[j]]=tile[i%th][j%tw]
    return out

